static int p2d89_emit_curves_round(P2D89_ShapeId id,const P2D89_Provider *p){if(id==P2D89_SHAPE_CIRCLE||id==P2D89_SHAPE_HOLLOW_CIRCLE)return p2d89_emit_ellipse(16384,16384,1,p);if(id==P2D89_SHAPE_ELLIPSE)return p2d89_emit_ellipse(16384,10240,1,p);if(id==P2D89_SHAPE_OVAL)return p2d89_emit_ellipse(16384,12288,1,p);if(id==P2D89_SHAPE_DONUT||id==P2D89_SHAPE_RING){if(!p2d89_emit_ellipse(16384,16384,1,p))return 0;return p2d89_emit_ellipse(8192,8192,0,p);}if(id==P2D89_SHAPE_SEMICIRCLE)return p2d89_i_semicircle(1,p);if(id==P2D89_SHAPE_QUARTER_CIRCLE||id==P2D89_SHAPE_SECTOR)return p2d89_i_quarter_circle(1,p);return 0;}
const P2D89_Submodule p2d89_submodule_curves_round = { { P2D89_MODULE_CURVES, "curves", "round", (unsigned int)(sizeof(shapes)/sizeof(shapes[0])) }, shapes, p2d89_emit_curves_round };
